    order_units = df_sales.groupby('Name')['Lineitem quantity'].sum()
    order_country = df_sales.groupby('Name')['Shipping Country'].first()
    order_df = pd.concat([order_units, order_country], axis=1)
    order_df.columns = ['total_units', 'Shipping Country']

    country_stats = order_df.groupby('Shipping Country').agg(
        total_units=('total_units', 'sum'),
        order_count=('total_units', 'count')
    )
    country_stats['avg_units_per_order'] = country_stats['total_units'] / country_stats['order_count']

    top10 = country_stats.nlargest(10, 'order_count')

    seg_results = [
        {"name": str(country), "value": round(float(row['avg_units_per_order']), 4)}
