import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np

    # Use last value per account_id per month (snapshot semantics)
    df['month_dt'] = df['month'].astype(str)
    snap = df.sort_values('month_dt').groupby(['account_id', 'month_dt', 'plan'], as_index=False).last()

    # seats per account: one row per account per month, so compute mean seats per account by plan
    # "seats per account" = total seats / number of accounts, per plan
    plan_seats = snap.groupby('plan').agg(
        total_seats=('seats', 'sum'),
        account_count=('account_id', 'nunique')
    ).reset_index()
    plan_seats['seats_per_account'] = plan_seats['total_seats'] / plan_seats['account_count']

    seg_results = []
    for _, row in plan_seats.iterrows():
        seg_results.append({"name": str(row['plan']), "value": float(round(row['seats_per_account'], 4))})

    result['segments'].append({
        "segment_column": "plan",
        "metric_column": "seats",
        "aggregation": "ratio",
        "label": "seats_per_account",
        "results": seg_results
    })

    # Also: mean seats per account-month snapshot by plan (distribution of per-account seat counts)
    mean_seats = snap.groupby('plan')['seats'].mean().reset_index()
    mean_results = [{"name": str(r['plan']), "value": float(round(r['seats'], 4))} for _, r in mean_seats.iterrows()]

    result['segments'].append({
        "segment_column": "plan",
        "metric_column": "seats",
        "aggregation": "mean",
        "label": None,
        "results": mean_results
    })

    # Count of accounts per plan
    acct_count = snap.groupby('plan')['account_id'].nunique().reset_index()
    count_results = [{"name": str(r['plan']), "value": float(r['account_id'])} for _, r in acct_count.iterrows()]

    result['segments'].append({
